SELECT bs.branch_stock_code AS branchStockCode, bs.branch_code AS branchCode, bs.material_code AS materialCode, mg.group_name AS groupName, m.material_name AS materialName, m.unit AS unit, bs.received_at AS receivedAt, bs.expire_date AS expireDate, bs.current_qty AS currentQty, COALESCE(ss.safe_stock_qty, 0) AS safeStockQty FROM branch_stock bs JOIN material m ON bs.material_code = m.material_code JOIN material_group mg ON m.material_group_id = mg.material_group_id LEFT JOIN branch_material_safety_stock ss ON ss.branch_code = bs.branch_code AND ss.material_code = bs.material_code WHERE bs.branch_code = #{branchCode} AND bs.current_qty > 0
AND mg.material_group_id = #{materialGroupId}
AND m.material_name = #{materialName}
AND (bs.branch_stock_code LIKE CONCAT('%', #{keyword}, '%') OR m.material_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY
bs.expire_date bs.received_at
DESC ASC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM branch_stock bs JOIN material m ON bs.material_code = m.material_code JOIN material_group mg ON m.material_group_id = mg.material_group_id WHERE bs.branch_code = #{branchCode} AND bs.current_qty > 0
AND mg.material_group_id = #{materialGroupId}
AND m.material_name = #{materialName}
AND (bs.branch_stock_code LIKE CONCAT('%', #{keyword}, '%') OR m.material_name LIKE CONCAT('%', #{keyword}, '%'))
